'use client';
/**
 * The hero's signature: sew the patch on yourself.
 *
 * The needle rides the tailor's-chalk line around the saffron patch. Drag it (pointer projected onto the seam, only
 * within a window around where the needle is, so it can't jump across the patch) and the running stitch appears
 * behind it — the svg-path-draw technique, a mask whose dash offset is the progress, driven by the pointer instead of
 * a clock. Drag back to unpick. The needle turns corners on a spring, and the working thread is a short verlet rope:
 * inextensible, with the friction of thread on denim, so it trails, whips round corners and comes to rest where it
 * lies. Finishing the last stitch ties it off: the tail is pulled through to a knot and the patch settles onto the
 * cloth.
 *
 * Twins: the needle is a slider (←/→ one stitch, Page Up/Down a side, Home/End); "Finish for me" plays the one-shot
 * stitch from wherever you are; "Unpick" starts again. On first view the needle sews the first side by itself and
 * hands over. Reduced motion: no intro, the patch starts sewn, every change is a jump and the thread lies still.
 */
import { useCallback, useEffect, useId, useRef, useState, type KeyboardEvent, type PointerEvent } from 'react';
import { animate } from 'motion/react';
import { duration as D, easing, spring, springToLinear, useIsomorphicLayoutEffect, useRafLoop, useStudioMotion } from '../../../motion';
import styles from './styles.module.css';

const PATCH = 'M118 74 296 62 304 226 126 238Z';
const SEAM_PTS: readonly [number, number][] = [[134, 88], [282, 78], [288, 212], [140, 222], [134, 88]];
const SEAM = `M${SEAM_PTS.slice(0, 4).map(([x, y]) => `${x} ${y}`).join(' ')}Z`;
const STITCHES = 24;
const NEEDLE = 88; // user units, eye to tip
const ROPE = 15; // segments
const SEG = 7.2; // segment length (≈ 108 units of thread)
const KNOT = 0.9; // segment length once tied off
const POP = springToLinear(spring.pop);

/* ── seam geometry ─────────────────────────────────────────────────────── */
const SEGS = SEAM_PTS.slice(1).map(([x, y], i) => {
  const [x0, y0] = SEAM_PTS[i];
  const len = Math.hypot(x - x0, y - y0);
  return { x0, y0, dx: (x - x0) / len, dy: (y - y0) / len, len };
});
const TOTAL = SEGS.reduce((t, s) => t + s.len, 0);
function at(p: number): { x: number; y: number; tx: number; ty: number } {
  let s = Math.max(0, Math.min(1, p)) * TOTAL;
  for (const g of SEGS) {
    if (s <= g.len || g === SEGS[SEGS.length - 1]) return { x: g.x0 + g.dx * Math.min(s, g.len), y: g.y0 + g.dy * Math.min(s, g.len), tx: g.dx, ty: g.dy };
    s -= g.len;
  }
  return { x: SEAM_PTS[0][0], y: SEAM_PTS[0][1], tx: 1, ty: 0 };
}
/** Tangent averaged over ±14 units of seam, so corners ease the needle round instead of snapping it. */
function heading(p: number): number {
  const d = 14 / TOTAL;
  const a = at(p - d), b = at(p), c = at(p + d);
  return Math.atan2(a.ty + b.ty + c.ty, a.tx + b.tx + c.tx);
}
const SAMPLES = Array.from({ length: 721 }, (_, i) => { const p = i / 720; const q = at(p); return { p, x: q.x, y: q.y }; });
function project(x: number, y: number, lo: number, hi: number): number {
  let best = lo, bd = Infinity;
  for (const s of SAMPLES) {
    if (s.p < lo || s.p > hi) continue;
    const d = (s.x - x) ** 2 + (s.y - y) ** 2;
    if (d < bd) { bd = d; best = s.p; }
  }
  return best;
}

/* ── the thread ────────────────────────────────────────────────────────── */
interface Pt { x: number; y: number; px: number; py: number }
/** A thread lying behind the needle in a loose curve (used at start, after unpicking, and under reduced motion). */
function layRope(ex: number, ey: number, ang: number, seg: number): Pt[] {
  const pts: Pt[] = [];
  let a = ang + Math.PI; // trail behind the eye
  let x = ex, y = ey;
  for (let i = 0; i <= ROPE; i++) {
    pts.push({ x, y, px: x, py: y });
    a += 0.11; // a gentle curl
    x += Math.cos(a) * seg; y += Math.sin(a) * seg;
  }
  return pts;
}
function ropePath(pts: Pt[], dx = 0, dy = 0): string {
  let d = `M${(pts[0].x + dx).toFixed(1)} ${(pts[0].y + dy).toFixed(1)}`;
  for (let i = 1; i < pts.length - 1; i++) {
    const mx = (pts[i].x + pts[i + 1].x) / 2, my = (pts[i].y + pts[i + 1].y) / 2;
    d += `Q${(pts[i].x + dx).toFixed(1)} ${(pts[i].y + dy).toFixed(1)} ${(mx + dx).toFixed(1)} ${(my + dy).toFixed(1)}`;
  }
  const l = pts[pts.length - 1];
  return `${d}L${(l.x + dx).toFixed(1)} ${(l.y + dy).toFixed(1)}`;
}

export function NeedlePatch() {
  const { reduced } = useStudioMotion();
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, '');
  const wrap = useRef<HTMLDivElement>(null);
  const svg = useRef<SVGSVGElement>(null);
  const needle = useRef<SVGGElement>(null);
  const needleShadow = useRef<SVGGElement>(null);
  const mask = useRef<SVGPathElement>(null);
  const thread = useRef<SVGPathElement>(null);
  const threadShadow = useRef<SVGPathElement>(null);
  const knot = useRef<SVGCircleElement>(null);
  const patch = useRef<SVGGElement>(null);
  const glint = useRef<SVGPathElement>(null);

  const p = useRef(reduced ? 1 : 0);
  const ang = useRef(heading(p.current));
  const angV = useRef(0);
  const seg = useRef(reduced ? KNOT : SEG);
  const rope = useRef<Pt[]>(layRope(at(p.current).x, at(p.current).y, ang.current, seg.current));
  const drag = useRef<{ id: number; offset: number } | null>(null);
  const tween = useRef<{ stop: () => void } | null>(null);
  const anims = useRef(new Set<Animation>());
  const acc = useRef(0);
  const awake = useRef(false);
  const [running, setRunning] = useState(false);
  const [stitch, setStitch] = useState(Math.round(p.current * STITCHES));
  const [say, setSay] = useState('');
  const [handed, setHanded] = useState(reduced);
  const done = stitch >= STITCHES;
  const doneRef = useRef(done);

  const wake = useCallback(() => { if (!awake.current) { awake.current = true; setRunning(true); } }, []);
  const play = (el: Element | null, k: Keyframe[], o: KeyframeAnimationOptions) => {
    if (!el || typeof el.animate !== 'function') return;
    const a = el.animate(k, o);
    anims.current.add(a);
    const off = () => anims.current.delete(a);
    a.finished.then(off, off);
  };

  /** Write the current state into the drawing (no React render). */
  const draw = useCallback(() => {
    const q = at(p.current);
    const deg = (ang.current * 180) / Math.PI;
    needle.current?.setAttribute('transform', `translate(${q.x.toFixed(2)} ${q.y.toFixed(2)}) rotate(${deg.toFixed(2)})`);
    needleShadow.current?.setAttribute('transform', `translate(${(q.x + 2.5).toFixed(2)} ${(q.y + 3.5).toFixed(2)}) rotate(${deg.toFixed(2)})`);
    if (mask.current) mask.current.style.strokeDashoffset = String(1 - p.current);
    const pts = rope.current;
    thread.current?.setAttribute('d', ropePath(pts));
    threadShadow.current?.setAttribute('d', ropePath(pts, 1.4, 2));
    if (knot.current) knot.current.style.opacity = seg.current < SEG * 0.4 ? '1' : '0';
  }, []);

  /** Progress changed: update the readout, and tie off or untie when crossing the last stitch. */
  const setProgress = useCallback((v: number) => {
    p.current = Math.max(0, Math.min(1, v));
    const n = Math.round(p.current * STITCHES);
    setStitch((s) => (s === n ? s : n));
    const nowDone = p.current >= 0.999;
    if (nowDone !== doneRef.current) {
      doneRef.current = nowDone;
      if (nowDone) {
        setSay('Patch sewn on.');
        if (!reduced) {
          play(patch.current, [{ transform: 'scale(1)' }, { transform: 'scale(0.986)', offset: 0.3 }, { transform: 'scale(1)' }], { duration: POP.duration, easing: POP.easing });
          play(glint.current, [{ strokeDashoffset: 0.12, opacity: 1 }, { strokeDashoffset: -0.88, opacity: 0 }], { duration: D.cinematic, easing: 'cubic-bezier(0.65, 0, 0.35, 1)' });
        }
      } else {
        // Untied: the thread comes back out at full length, trailing behind the needle.
        seg.current = SEG;
        const q = at(p.current);
        rope.current = layRope(q.x, q.y, ang.current, SEG);
      }
    }
    if (reduced) {
      ang.current = heading(p.current);
      seg.current = nowDone ? KNOT : SEG;
      const q = at(p.current);
      rope.current = layRope(q.x, q.y, ang.current, seg.current);
      draw();
    } else wake();
  }, [draw, reduced, wake]);

  // The loop: needle heading spring, rope physics at a fixed 120 Hz, tie-off; sleeps when everything has settled.
  useRafLoop(wrap, (dt) => {
    const q = at(p.current);
    // Heading: a press spring towards the seam's (smoothed) tangent, by the shortest way round.
    let diff = heading(p.current) - ang.current;
    diff = Math.atan2(Math.sin(diff), Math.cos(diff));
    const k = spring.press;
    angV.current += ((k.stiffness * diff - k.damping * angV.current) / k.mass) * dt;
    ang.current += angV.current * dt;
    // Tie-off pulls the tail through to a knot; untying lets it out again.
    const want = doneRef.current ? KNOT : SEG;
    seg.current += (want - seg.current) * Math.min(1, dt * 9);
    // Rope: verlet with heavy friction (thread on cloth) and inextensible segments; the first point rides the eye.
    acc.current += dt;
    let moved = 0;
    const pts = rope.current;
    while (acc.current >= 1 / 120) {
      acc.current -= 1 / 120;
      for (let i = 1; i < pts.length; i++) {
        const r = pts[i];
        const vx = (r.x - r.px) * 0.8, vy = (r.y - r.py) * 0.8;
        r.px = r.x; r.py = r.y; r.x += vx; r.y += vy;
        moved = Math.max(moved, Math.abs(vx) + Math.abs(vy));
      }
      pts[0].x = q.x; pts[0].y = q.y; pts[0].px = q.x; pts[0].py = q.y;
      for (let it = 0; it < 6; it++) {
        for (let i = 0; i < pts.length - 1; i++) {
          const a = pts[i], b = pts[i + 1];
          const dx = b.x - a.x, dy = b.y - a.y;
          const d = Math.hypot(dx, dy) || 0.0001;
          const f = (d - seg.current) / d;
          if (i === 0) { b.x -= dx * f; b.y -= dy * f; }
          else { a.x += dx * f * 0.5; a.y += dy * f * 0.5; b.x -= dx * f * 0.5; b.y -= dy * f * 0.5; }
        }
      }
    }
    draw();
    const settling = Math.abs(diff) > 0.002 || Math.abs(angV.current) > 0.01 || Math.abs(seg.current - want) > 0.02 || moved > 0.02;
    if (!drag.current && !tween.current && !settling) { awake.current = false; setRunning(false); }
  }, running && !reduced);

  // First paint (before the browser paints, so the needle never shows at the origin), and a reduced-motion switch.
  useIsomorphicLayoutEffect(() => {
    if (reduced) { tween.current?.stop(); tween.current = null; setHanded(true); setProgress(p.current); }
    draw();
  }, [reduced, draw, setProgress]);
  useEffect(() => () => { tween.current?.stop(); anims.current.forEach((a) => a.cancel()); }, []);

  const sewTo = useCallback((target: number, ms: number, delay = 0) => {
    tween.current?.stop();
    if (reduced) { setProgress(target); return; }
    const a = animate(p.current, target, { duration: ms / 1000, delay: delay / 1000, ease: [...easing.inOut], onUpdate: (v) => setProgress(v) });
    tween.current = a;
    wake();
    void a.then(() => { if (tween.current === a) { tween.current = null; setHanded(true); wake(); } });
  }, [reduced, setProgress, wake]);

  // On first view the needle sews the top edge itself, then hands over.
  useEffect(() => {
    if (reduced) return;
    sewTo(SEGS[0].len / TOTAL, D.epic, D.cinematic);
    return () => { tween.current?.stop(); tween.current = null; };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const toSvg = (x: number, y: number) => {
    const m = svg.current?.getScreenCTM();
    if (!m) return { x: 0, y: 0 };
    const v = new DOMPoint(x, y).matrixTransform(m.inverse());
    return { x: v.x, y: v.y };
  };
  const onDown = (e: PointerEvent<SVGRectElement>) => {
    if (e.button !== 0) return;
    tween.current?.stop();
    tween.current = null;
    setHanded(true);
    const v = toSvg(e.clientX, e.clientY);
    const grab = project(v.x, v.y, Math.max(0, p.current - 0.04), Math.min(1, p.current + NEEDLE / TOTAL + 0.06));
    drag.current = { id: e.pointerId, offset: grab - p.current };
    e.currentTarget.setPointerCapture?.(e.pointerId);
    wrap.current?.setAttribute('data-sewing', '');
    wake();
  };
  const onMove = (e: PointerEvent<SVGRectElement>) => {
    const d = drag.current;
    if (!d || d.id !== e.pointerId) return;
    const v = toSvg(e.clientX, e.clientY);
    const c = p.current + d.offset;
    setProgress(project(v.x, v.y, Math.max(0, c - 0.1), Math.min(1, c + 0.1)) - d.offset);
  };
  const onUp = (e: PointerEvent<SVGRectElement>) => {
    if (drag.current?.id !== e.pointerId) return;
    drag.current = null;
    wrap.current?.removeAttribute('data-sewing');
    wake();
  };
  const onKey = (e: KeyboardEvent<SVGGElement>) => {
    const n = Math.round(p.current * STITCHES);
    const to = e.key === 'ArrowRight' || e.key === 'ArrowUp' ? n + 1 : e.key === 'ArrowLeft' || e.key === 'ArrowDown' ? n - 1
      : e.key === 'PageUp' ? n + STITCHES / 4 : e.key === 'PageDown' ? n - STITCHES / 4 : e.key === 'Home' ? 0 : e.key === 'End' ? STITCHES : null;
    if (to === null) return;
    e.preventDefault();
    setHanded(true);
    const target = Math.max(0, Math.min(STITCHES, to)) / STITCHES;
    sewTo(target, Math.max(D.fast, Math.abs(target - p.current) * D.epic));
  };

  const finish = () => { setHanded(true); sewTo(1, Math.max(D.slow, (1 - p.current) * D.epic * 1.6)); };
  const unpick = () => {
    if (p.current <= 0) return;
    setHanded(true);
    setSay('Unpicked. The needle is back at the first stitch.');
    sewTo(0, Math.max(D.moderate, p.current * D.slow * 1.4));
  };

  const valueText = done ? 'Patch sewn on, all 24 stitches' : `${stitch} of ${STITCHES} stitches sewn`;
  return (
    <div ref={wrap} className={styles.heroArtWrap}>
      <svg ref={svg} viewBox="0 0 400 320" className={styles.heroArt} role="group" aria-label="Sew the patch on" aria-describedby={`${uid}-hint`}>
        <defs>
          <pattern id={`${uid}-twill`} width="10" height="10" patternUnits="userSpaceOnUse" patternTransform="rotate(-35)">
            <path d="M0 5h10" stroke="#f3efe6" strokeOpacity="0.07" strokeWidth="3" />
          </pattern>
          <pattern id={`${uid}-weave`} width="5" height="5" patternUnits="userSpaceOnUse" patternTransform="rotate(-4)">
            <path d="M0 2.5h5M2.5 0v5" stroke="#7a4a0a" strokeOpacity="0.09" strokeWidth="1" />
          </pattern>
          <linearGradient id={`${uid}-saffron`} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0" stopColor="#f6c66b" />
            <stop offset="1" stopColor="#e09f3a" />
          </linearGradient>
          <linearGradient id={`${uid}-steel`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#f4f6fb" />
            <stop offset="0.45" stopColor="#c3cad9" />
            <stop offset="1" stopColor="#7f889d" />
          </linearGradient>
          <filter id={`${uid}-soft`} x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation="5" /></filter>
          <filter id={`${uid}-softer`} x="-20%" y="-60%" width="140%" height="220%"><feGaussianBlur stdDeviation="1.4" /></filter>
          <mask id={`${uid}-sew`} maskUnits="userSpaceOnUse" x="0" y="0" width="400" height="320">
            <path ref={mask} d={SEAM} fill="none" stroke="#fff" strokeWidth="18" pathLength={1} strokeDasharray="1 1" style={{ strokeDashoffset: 1 - p.current }} />
          </mask>
        </defs>
        <g aria-hidden="true">
          <rect width="400" height="320" fill={`url(#${uid}-twill)`} />
          {/* The patch lies on the denim: a soft shadow down and to the right of the one top-left light. */}
          <path d={PATCH} transform="translate(5 7)" fill="#0b1122" opacity="0.5" filter={`url(#${uid}-soft)`} />
          <g ref={patch} className={styles.patch}>
            <path d={PATCH} fill={`url(#${uid}-saffron)`} />
            <path d={PATCH} fill={`url(#${uid}-weave)`} />
            <path d={PATCH} fill="none" stroke="#fff8e6" strokeOpacity="0.45" strokeWidth="1.5" transform="translate(-0.5 -0.5)" />
            <path d={PATCH} fill="none" stroke="#1e2a4a" strokeOpacity="0.25" strokeWidth="2" />
            {/* Tailor's chalk: where the stitches go. */}
            <path d={SEAM} fill="none" stroke="#fffaf0" strokeOpacity="0.75" strokeWidth="1.4" strokeDasharray="1.5 4.5" strokeLinecap="round" />
            {/* The running stitch, revealed by the mask as the needle moves. */}
            <path d={SEAM} fill="none" stroke="#0e1426" strokeOpacity="0.35" strokeWidth="5" pathLength={STITCHES} strokeDasharray="0.56 0.44" strokeDashoffset="-0.22" strokeLinecap="round" transform="translate(0.8 1.2)" mask={`url(#${uid}-sew)`} />
            <path d={SEAM} fill="none" stroke="#1e2a4a" strokeWidth="5" pathLength={STITCHES} strokeDasharray="0.56 0.44" strokeDashoffset="-0.22" strokeLinecap="round" mask={`url(#${uid}-sew)`} />
            <path ref={glint} d={SEAM} fill="none" stroke="#fffaf0" strokeWidth="2.4" pathLength={1} strokeDasharray="0.12 0.88" strokeLinecap="round" opacity="0" />
          </g>
          <path ref={threadShadow} fill="none" stroke="#070b16" strokeOpacity="0.4" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" />
          <path ref={thread} fill="none" stroke="#f3efe6" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" />
          <g ref={needleShadow} opacity="0.45" filter={`url(#${uid}-softer)`}>
            <path d={`M0 -2.6L${NEEDLE - 16} -1.9L${NEEDLE} 0L${NEEDLE - 16} 1.9L0 2.6A2.6 2.6 0 0 1 0 -2.6Z`} fill="#070b16" />
          </g>
          <circle ref={knot} r="2.6" fill="#f3efe6" stroke="#1e2a4a" strokeWidth="1" opacity="0" cx={SEAM_PTS[0][0]} cy={SEAM_PTS[0][1]} />
        </g>
        <g
          ref={needle}
          className={styles.needle}
          role="slider"
          tabIndex={0}
          aria-label="Needle"
          aria-valuemin={0}
          aria-valuemax={STITCHES}
          aria-valuenow={stitch}
          aria-valuetext={valueText}
          aria-describedby={`${uid}-hint`}
          onKeyDown={onKey}
        >
          <path d={`M0 -2.6L${NEEDLE - 16} -1.9L${NEEDLE} 0L${NEEDLE - 16} 1.9L0 2.6A2.6 2.6 0 0 1 0 -2.6Z`} fill={`url(#${uid}-steel)`} stroke="#59627a" strokeWidth="0.5" />
          <path d={`M3 -1.6L${NEEDLE - 20} -1.2`} stroke="#fff" strokeOpacity="0.85" strokeWidth="0.8" strokeLinecap="round" />
          <ellipse cx="7" cy="0" rx="3.8" ry="0.95" fill="#1e2a4a" />
          <rect className={styles.needleHit} x="-14" y="-24" width={NEEDLE + 28} height="48" rx="24" fill="transparent"
            onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp} />
        </g>
      </svg>
      <div className={styles.sewBar}>
        <p id={`${uid}-hint`} className={styles.sewHint}>
          <span className={styles.sewCount} aria-hidden="true">{String(stitch).padStart(2, '0')}/{STITCHES}</span>
          {done ? 'Sewn on. That is the whole idea.' : handed ? 'Your turn: drag the needle along the chalk line.' : 'Threading the needle…'}
        </p>
        <div className={styles.sewActions}>
          {done ? null : <button type="button" className={styles.denimKey} onClick={finish}>Finish for me</button>}
          <button type="button" className={styles.denimKey} onClick={unpick} aria-disabled={stitch === 0 || undefined}>Unpick</button>
        </div>
      </div>
      <p className="mk-sr-only" role="status">{say}</p>
    </div>
  );
}

'use client';
/**
 * The participation flow: pledge one mend. Errors appear on blur (once a field was touched) and on submit, with
 * aria-invalid + aria-describedby; a failed submit moves focus to the first problem and gives the key a short shake.
 * Nothing personal is required (the name is optional), showing the entry in the gallery is opt-in, and nothing leaves
 * the page.
 *
 * The submit key follows the morph-submit-button technique: the pill collapses into a ring whose arc fills ever more
 * slowly while the (simulated) request runs, closes, draws a check, and only then hands over to the confirmation —
 * with a small burst of patches thrown from the key, once, for the person's own pledge. Every step starts from what is
 * on screen, and everything is cancelled on edit or unmount. Reduced motion: no morph, arc or burst; the label says
 * "Pledging…" and the confirmation appears.
 */
import { useEffect, useId, useRef, useState, type FormEvent } from 'react';
import { cssEase, duration as D, spring, springToLinear, useStudioMotion } from '../../../motion';
import { CAFES, CATEGORIES } from './data';
import styles from './styles.module.css';

export interface Pledge { item: string; category: string; where: string; name: string; gallery: boolean }
type Field = 'item' | 'category' | 'where' | 'name';
type Phase = 'idle' | 'sending' | 'success';
const ORDER: Field[] = ['item', 'category', 'where', 'name'];
const LATENCY = 900; // simulated request
const SETTLE = springToLinear(spring.settle);
const BURST = ['#f0b44c', '#f0b44c', '#ff8a6b', '#34478a', '#f0b44c', '#f3efe6', '#ff8a6b', '#34478a', '#f0b44c', '#f0b44c'];

function validate(v: Pledge): Partial<Record<Field, string>> {
  const e: Partial<Record<Field, string>> = {};
  const item = v.item.trim();
  if (item.length < 3) e.item = item ? 'A few more letters, please — at least 3.' : 'Tell us the one thing you will mend.';
  else if (item.length > 60) e.item = 'Keep it under 60 characters so it fits the share card.';
  if (!v.category) e.category = 'Choose what kind of thing it is.';
  if (!v.where) e.where = 'Choose a café, or “At home”.';
  if (v.name.trim().length > 40) e.name = 'Keep the name under 40 characters.';
  return e;
}

export function PledgeForm({ onPledged, onEdit }: { onPledged: (p: Pledge) => void; onEdit: () => void }) {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const [v, setV] = useState<Pledge>({ item: '', category: '', where: '', name: '', gallery: false });
  const [touched, setTouched] = useState<Partial<Record<Field, boolean>>>({});
  const [tried, setTried] = useState(false);
  const [status, setStatus] = useState<'idle' | 'sending' | 'done'>('idle');
  const [phase, setPhase] = useState<Phase>('idle');
  const [say, setSay] = useState('');
  const doneHead = useRef<HTMLHeadingElement>(null);
  const donePanel = useRef<HTMLDivElement>(null);
  const check = useRef<SVGPathElement>(null);
  const wrap = useRef<HTMLDivElement>(null);
  const burstLayer = useRef<HTMLDivElement>(null);
  const btn = useRef<HTMLButtonElement>(null);
  const label = useRef<HTMLSpanElement>(null);
  const ring = useRef<SVGSVGElement>(null);
  const arc = useRef<SVGCircleElement>(null);
  const mark = useRef<SVGPathElement>(null);
  const run = useRef(0);
  const live = useRef(new Set<Animation>());
  const timers = useRef(new Set<number>());
  const burstFrom = useRef<{ x: number; y: number } | null>(null);

  const stopAll = () => {
    run.current++;
    live.current.forEach((a) => a.cancel()); live.current.clear();
    timers.current.forEach((t) => window.clearTimeout(t)); timers.current.clear();
  };
  useEffect(() => () => {
    run.current++;
    live.current.forEach((a) => a.cancel());
    timers.current.forEach((t) => window.clearTimeout(t));
    burstLayer.current?.replaceChildren();
  }, []);
  const animate = (el: Element | null, k: Keyframe[], o: KeyframeAnimationOptions): Animation | null => {
    if (!el || typeof el.animate !== 'function') return null;
    const a = el.animate(k, o);
    live.current.add(a);
    const off = () => live.current.delete(a);
    a.finished.then(off, off);
    return a;
  };
  const wait = (ms: number) => new Promise<void>((resolve) => {
    const t = window.setTimeout(() => { timers.current.delete(t); resolve(); }, ms);
    timers.current.add(t);
  });

  /** A handful of patches thrown up from the key on ballistic arcs (sampled into keyframes), then removed. */
  const burst = (x: number, y: number) => {
    const layer = burstLayer.current;
    if (!layer || reduced || typeof layer.animate !== 'function') return;
    BURST.forEach((c, i) => {
      const el = document.createElement('span');
      el.className = styles.burstPatch;
      el.style.setProperty('--c', c);
      el.style.left = `${x}px`;
      el.style.top = `${y}px`;
      layer.appendChild(el);
      const ang = (-150 + (i / (BURST.length - 1)) * 120 + (Math.random() - 0.5) * 14) * (Math.PI / 180);
      const v = 300 + Math.random() * 190, g = 1150, spin = (Math.random() - 0.5) * 720, life = 0.8 + Math.random() * 0.25;
      const frames: Keyframe[] = [];
      for (let k = 0; k <= 10; k++) {
        const t = (k / 10) * life;
        const px = Math.cos(ang) * v * t, py = Math.sin(ang) * v * t + 0.5 * g * t * t;
        frames.push({ transform: `translate(-50%, -50%) translate(${px.toFixed(1)}px, ${py.toFixed(1)}px) rotate(${(spin * t).toFixed(0)}deg) scale(${k === 0 ? 0.3 : 1})`, opacity: k < 7 ? 1 : 1 - (k - 6) / 4 });
      }
      const a = animate(el, frames, { duration: life * 1000, easing: 'linear', fill: 'forwards' });
      const gone = () => el.remove();
      if (a) a.finished.then(gone, gone); else gone();
    });
  };

  const errors = validate(v);
  const show = (f: Field) => (tried || touched[f]) && errors[f];
  const id = (s: string) => `${uid}-${s}`;
  const set = <K extends keyof Pledge>(k: K, val: Pledge[K]) => setV((p) => ({ ...p, [k]: val }));
  const described = (f: Field, hint?: boolean) => [hint ? id(`${f}-hint`) : '', show(f) ? id(`${f}-err`) : ''].filter(Boolean).join(' ') || undefined;

  useEffect(() => {
    if (status !== 'done') return;
    doneHead.current?.focus();
    const from = burstFrom.current;
    burstFrom.current = null;
    if (reduced) return;
    if (from) burst(from.x, from.y);
    const panel = donePanel.current;
    const list: Animation[] = [];
    if (panel && typeof panel.animate === 'function') list.push(panel.animate([{ opacity: 0, transform: 'translateY(14px) scale(0.98)' }, { opacity: 1, transform: 'none' }], { duration: SETTLE.duration, easing: SETTLE.easing }));
    const p = check.current;
    if (p && typeof p.animate === 'function') list.push(p.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], { duration: D.slow, delay: D.fast, easing: cssEase('emphasized'), fill: 'backwards' }));
    return () => list.forEach((a) => a.cancel());
  }, [status, reduced]); // eslint-disable-line react-hooks/exhaustive-deps

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    if (status === 'sending') return;
    setTried(true);
    const bad = ORDER.filter((f) => errors[f]);
    if (bad.length) {
      setSay(`${bad.length === 1 ? 'One answer needs' : `${bad.length} answers need`} attention.`);
      const first = bad[0];
      const target = first === 'category' ? document.querySelector<HTMLInputElement>(`input[name="${id('category')}"]`) : document.getElementById(id(first));
      target?.focus();
      if (!reduced) animate(btn.current, [{ transform: 'translateX(0)' }, { transform: 'translateX(-6px)' }, { transform: 'translateX(5px)' }, { transform: 'translateX(-3px)' }, { transform: 'translateX(0)' }], { duration: D.slow * 0.8, easing: 'ease-out' });
      return;
    }
    stopAll();
    const my = run.current;
    const pledge = { ...v, item: v.item.trim(), name: v.name.trim() };
    setStatus('sending');
    setPhase('sending');
    setSay('Saving your pledge…');
    const finish = () => {
      const b = btn.current?.getBoundingClientRect(), w = wrap.current?.getBoundingClientRect();
      burstFrom.current = b && w ? { x: b.left + b.width / 2 - w.left, y: b.top + b.height / 2 - w.top } : null;
      setStatus('done'); setPhase('idle'); setSay(''); onPledged(pledge);
    };
    if (reduced) { await wait(LATENCY); if (my === run.current) finish(); return; }

    // 1 · the pill collapses into a ring; the arc fills on a curve that never completes by itself.
    const b = btn.current;
    const from = b?.getBoundingClientRect();
    animate(label.current, [{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateY(-6px)' }], { duration: D.fast, easing: cssEase('exit'), fill: 'forwards' });
    if (b && from) animate(b, [{ width: `${from.width}px` }, { width: `${from.height}px` }], { duration: D.moderate, easing: cssEase('emphasized'), fill: 'forwards' });
    animate(ring.current, [{ opacity: 0, transform: 'scale(0.6)' }, { opacity: 1, transform: 'none' }], { duration: D.base, delay: D.moderate * 0.55, easing: cssEase('emphasized'), fill: 'both' });
    const fill = animate(arc.current, [{ strokeDashoffset: 1 }, { strokeDashoffset: 0.1 }], { duration: LATENCY * 1.5, delay: D.moderate * 0.55, easing: cssEase('enter'), fill: 'both' });
    await wait(LATENCY);
    if (my !== run.current) return;
    // 2 · the request is back: close the ring, draw the check, hold a beat, then the confirmation takes over.
    const atNow = arc.current ? parseFloat(getComputedStyle(arc.current).strokeDashoffset) || 0 : 0;
    fill?.cancel();
    animate(arc.current, [{ strokeDashoffset: atNow }, { strokeDashoffset: 0 }], { duration: D.fast, easing: cssEase('standard'), fill: 'forwards' });
    await wait(D.fast);
    if (my !== run.current) return;
    setPhase('success');
    animate(ring.current, [{ opacity: 1 }, { opacity: 0 }], { duration: D.base, easing: 'linear', fill: 'forwards' });
    animate(mark.current, [{ strokeDashoffset: 1, opacity: 1 }, { strokeDashoffset: 0, opacity: 1 }], { duration: D.moderate, delay: 60, easing: cssEase('emphasized'), fill: 'both' });
    await wait(D.moderate + D.base);
    if (my !== run.current) return;
    finish();
  };

  if (status === 'done') {
    return (
      <div ref={wrap} className={styles.pledgeWrap}>
      <div ref={donePanel} className={styles.done}>
        <svg viewBox="0 0 64 64" className={styles.doneMark} aria-hidden="true" focusable="false">
          <rect x="6" y="6" width="52" height="52" rx="4" className={styles.donePatch} />
          <path ref={check} d="M18 33l10 10 18-22" pathLength={1} className={styles.doneCheck} />
        </svg>
        <h3 ref={doneHead} tabIndex={-1} className={styles.doneTitle}>Pledged: {v.item.trim()}</h3>
        <p>
          See you in March. Mend it {v.where === 'At home' ? 'at home' : `at ${v.where}`} any day from 1 to 31 March 2027
          {v.gallery ? ', and your before-and-after can go in the gallery.' : '. Your pledge stays out of the gallery, as you chose.'}
        </p>
        <p className={styles.small}>Demo: nothing was sent or stored. Edit it, or make a share card below.</p>
        <button type="button" className={styles.ghost} onClick={() => { stopAll(); setStatus('idle'); onEdit(); }}>Edit pledge</button>
      </div>
      <div ref={burstLayer} className={styles.burstLayer} aria-hidden="true" />
      </div>
    );
  }

  return (
    <div ref={wrap} className={styles.pledgeWrap}>
    <form className={styles.form} onSubmit={(e) => void submit(e)} noValidate aria-describedby={id('privacy')}>
      <div className={styles.field}>
        <label htmlFor={id('item')} className={styles.label}>What will you mend?</label>
        <p id={id('item-hint')} className={styles.small}>One thing is plenty: a jumper, a lamp, a wobbly chair.</p>
        <input id={id('item')} className={styles.input} value={v.item} maxLength={80} autoComplete="off"
          aria-invalid={show('item') ? true : undefined} aria-describedby={described('item', true)}
          onChange={(e) => set('item', e.target.value)} onBlur={() => setTouched((t) => ({ ...t, item: true }))} />
        {show('item') ? <p id={id('item-err')} className={styles.error}>{errors.item}</p> : null}
      </div>

      <fieldset className={styles.field}>
        <legend className={styles.label}>What kind of thing is it?</legend>
        <div className={styles.choices}>
          {[...CATEGORIES, 'Something else'].map((c) => (
            <label key={c} className={styles.choice}>
              <input type="radio" name={id('category')} value={c} checked={v.category === c}
                aria-invalid={show('category') ? true : undefined} aria-describedby={show('category') ? id('category-err') : undefined}
                onChange={() => { set('category', c); setTouched((t) => ({ ...t, category: true })); }} />
              <span>{c}</span>
            </label>
          ))}
        </div>
        {show('category') ? <p id={id('category-err')} className={styles.error}>{errors.category}</p> : null}
      </fieldset>

      <div className={styles.field}>
        <label htmlFor={id('where')} className={styles.label}>Where will you mend it?</label>
        <select id={id('where')} className={styles.input} value={v.where}
          aria-invalid={show('where') ? true : undefined} aria-describedby={described('where')}
          onChange={(e) => set('where', e.target.value)} onBlur={() => setTouched((t) => ({ ...t, where: true }))}>
          <option value="">Choose…</option>
          <option>At home</option>
          {CAFES.map((c) => <option key={c}>{c}</option>)}
        </select>
        {show('where') ? <p id={id('where-err')} className={styles.error}>{errors.where}</p> : null}
      </div>

      <div className={styles.field}>
        <label htmlFor={id('name')} className={styles.label}>Name to show <span className={styles.optional}>(optional)</span></label>
        <p id={id('name-hint')} className={styles.small}>Leave it blank to stay anonymous.</p>
        <input id={id('name')} className={styles.input} value={v.name} maxLength={60} autoComplete="nickname"
          aria-invalid={show('name') ? true : undefined} aria-describedby={described('name', true)}
          onChange={(e) => set('name', e.target.value)} onBlur={() => setTouched((t) => ({ ...t, name: true }))} />
        {show('name') ? <p id={id('name-err')} className={styles.error}>{errors.name}</p> : null}
      </div>

      <label className={styles.check}>
        <input type="checkbox" checked={v.gallery} onChange={(e) => set('gallery', e.target.checked)} />
        <span>Show my before-and-after in the 2027 gallery (you can change your mind later)</span>
      </label>

      <div className={styles.submitRow}>
        <span className={styles.morphSlot}>
          {/* The slot keeps the widest label's width, so nothing around the key moves while it morphs. */}
          <span className={styles.morphSizer} aria-hidden="true"><span>Pledge my mend</span><span>Pledging…</span></span>
          <button ref={btn} type="submit" className={`${styles.primary} ${styles.morphKey}`} data-phase={phase}
            aria-busy={phase === 'sending' || undefined} aria-disabled={status === 'sending' || undefined}>
            <span ref={label} className={styles.morphLabel}>{status === 'sending' ? 'Pledging…' : 'Pledge my mend'}</span>
            <svg ref={ring} className={styles.morphRing} viewBox="0 0 24 24" aria-hidden="true" focusable="false">
              <circle className={styles.morphTrack} cx="12" cy="12" r="10" />
              <circle ref={arc} className={styles.morphArc} cx="12" cy="12" r="10" pathLength={1} transform="rotate(-90 12 12)" />
            </svg>
            <svg className={styles.morphMark} viewBox="0 0 24 24" aria-hidden="true" focusable="false">
              <path ref={mark} className={styles.morphCheck} d="m7 12.5 3.4 3.4L17.2 8.6" pathLength={1} />
            </svg>
          </button>
        </span>
        <p id={id('privacy')} className={styles.small}>No email needed. Demo: your pledge stays on this page.</p>
      </div>
      <p className="mk-sr-only" role="status" aria-live="polite">{say}</p>
    </form>
    <div ref={burstLayer} className={styles.burstLayer} aria-hidden="true" />
    </div>
  );
}

'use client';
/**
 * Share-card generator: a 1080 × 1080 canvas redrawn from the form, downloadable as a PNG and shareable as a file
 * where the browser supports it (navigator.canShare({ files })). The canvas has a written equivalent that updates
 * with the text; drawing waits for the page fonts so the PNG matches the preview.
 */
import { useEffect, useId, useRef, useState } from 'react';
import styles from './styles.module.css';

const THREADS = [
  { id: 'saffron', label: 'Saffron', color: '#f0b44c' },
  { id: 'coral', label: 'Coral', color: '#ff8a6b' },
  { id: 'chalk', label: 'Chalk', color: '#f3efe6' },
] as const;
type Thread = (typeof THREADS)[number]['id'];
const SIZE = 1080;

function wrap(ctx: CanvasRenderingContext2D, text: string, max: number): string[] {
  const words = text.split(/\s+/).filter(Boolean);
  const lines: string[] = [];
  let line = '';
  for (const w of words) {
    const next = line ? `${line} ${w}` : w;
    if (ctx.measureText(next).width > max && line) { lines.push(line); line = w; } else line = next;
  }
  if (line) lines.push(line);
  return lines;
}

function draw(canvas: HTMLCanvasElement, item: string, thread: Thread, fonts: { display: string; serif: string; mono: string }) {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const color = THREADS.find((t) => t.id === thread)?.color ?? '#f0b44c';
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.fillStyle = '#1e2a4a';
  ctx.fillRect(0, 0, SIZE, SIZE);
  // twill
  ctx.strokeStyle = 'rgba(243, 239, 230, 0.05)';
  ctx.lineWidth = 3;
  for (let x = -SIZE; x < SIZE; x += 18) { ctx.beginPath(); ctx.moveTo(x, SIZE); ctx.lineTo(x + SIZE, 0); ctx.stroke(); }
  ctx.fillStyle = '#c9cfe0';
  ctx.font = `500 30px ${fonts.mono}`;
  ctx.fillText('MEND MARCH · 1–31 MARCH 2027', 84, 120);
  ctx.fillStyle = '#f3efe6';
  ctx.font = `italic 72px ${fonts.serif}`;
  ctx.fillText('I’m mending my', 84, 300);
  let size = 128;
  let lines: string[] = [];
  for (; size >= 72; size -= 8) {
    ctx.font = `800 ${size}px ${fonts.display}`;
    lines = wrap(ctx, item || 'one thing', SIZE - 168);
    if (lines.length <= 3) break;
  }
  lines.slice(0, 3).forEach((l, i) => ctx.fillText(l, 84, 300 + size * 1.02 * (i + 1)));
  // running stitch
  ctx.setLineDash([26, 18]);
  ctx.lineWidth = 6;
  ctx.lineCap = 'round';
  ctx.strokeStyle = color;
  ctx.beginPath(); ctx.moveTo(84, 812); ctx.bezierCurveTo(330, 772, 520, 852, 700, 800); ctx.stroke();
  // patch
  ctx.save();
  ctx.translate(856, 866); ctx.rotate(-0.07);
  ctx.setLineDash([]);
  ctx.fillStyle = color;
  ctx.fillRect(-110, -110, 220, 220);
  ctx.setLineDash([16, 12]);
  ctx.lineWidth = 5;
  ctx.strokeStyle = '#1e2a4a';
  ctx.strokeRect(-92, -92, 184, 184);
  ctx.restore();
  ctx.setLineDash([]);
  ctx.fillStyle = '#c9cfe0';
  ctx.font = `500 28px ${fonts.mono}`;
  ctx.fillText('THE MENDING COMMONS', 84, 1000);
}

export function ShareCard({ item: initial }: { item: string }) {
  const uid = useId();
  const canvas = useRef<HTMLCanvasElement>(null);
  const [item, setItem] = useState(initial);
  const [thread, setThread] = useState<Thread>('saffron');
  const [canShareFiles, setCanShareFiles] = useState(false);
  const [note, setNote] = useState('');
  useEffect(() => { if (initial) setItem(initial); }, [initial]);

  useEffect(() => {
    const c = canvas.current;
    if (!c) return;
    let alive = true;
    const cs = getComputedStyle(c);
    const fonts = {
      display: cs.getPropertyValue('--mk-font-display').trim() || 'sans-serif',
      serif: cs.getPropertyValue('--mk-font-serif').trim() || 'serif',
      mono: cs.getPropertyValue('--mk-font-mono').trim() || 'monospace',
    };
    draw(c, item, thread, fonts);
    // Redraw once the webfonts are ready so the PNG uses them, not the fallback.
    document.fonts?.ready.then(() => { if (alive) draw(c, item, thread, fonts); }, () => {});
    return () => { alive = false; };
  }, [item, thread]);

  useEffect(() => {
    try {
      const nav = navigator as Navigator & { canShare?: (d: ShareData) => boolean };
      setCanShareFiles(typeof nav.share === 'function' && !!nav.canShare?.({ files: [new File([''], 'probe.png', { type: 'image/png' })] }));
    } catch { setCanShareFiles(false); }
  }, []);

  const toBlob = () => new Promise<Blob | null>((resolve) => canvas.current ? canvas.current.toBlob(resolve, 'image/png') : resolve(null));
  const download = async () => {
    const blob = await toBlob();
    if (!blob) { setNote('Could not create the image in this browser.'); return; }
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'mend-march-2027.png';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    setNote('Saved mend-march-2027.png.');
  };
  const share = async () => {
    const blob = await toBlob();
    if (!blob) return;
    try {
      await navigator.share({ files: [new File([blob], 'mend-march-2027.png', { type: 'image/png' })], title: 'Mend March 2027' });
      setNote('Shared.');
    } catch (e) { if ((e as Error).name !== 'AbortError') setNote('Sharing failed — download the image instead.'); }
  };

  const text = item.trim() || 'one thing';
  return (
    <div className={styles.card}>
      <div className={styles.cardControls}>
        <label htmlFor={`${uid}-item`} className={styles.label}>Text on the card</label>
        <div className={styles.cardInputRow}>
          <span aria-hidden="true" className={styles.cardPrefix}>I’m mending my</span>
          <input id={`${uid}-item`} className={styles.input} value={item} maxLength={60} placeholder="one thing" onChange={(e) => setItem(e.target.value)} aria-describedby={`${uid}-prefix`} />
        </div>
        <p id={`${uid}-prefix`} className={styles.small}>The card reads “I’m mending my …”. Up to 60 characters.</p>
        <fieldset className={styles.threads}>
          <legend className={styles.label}>Thread colour</legend>
          {THREADS.map((t) => (
            <label key={t.id} className={styles.thread}>
              <input type="radio" name={`${uid}-thread`} checked={thread === t.id} onChange={() => setThread(t.id)} />
              <span className={styles.swatch} style={{ background: t.color }} aria-hidden="true" />
              {t.label}
            </label>
          ))}
        </fieldset>
        <div className={styles.cardActions}>
          <button type="button" className={styles.primary} onClick={() => void download()}>Download PNG</button>
          {canShareFiles ? <button type="button" className={styles.ghost} onClick={() => void share()}>Share image…</button> : null}
        </div>
        <p className={styles.small} aria-live="polite">{note || 'Your card is made in this browser; nothing is uploaded.'}</p>
      </div>
      <canvas ref={canvas} width={SIZE} height={SIZE} className={styles.canvas} role="img"
        aria-label={`Share card preview: I’m mending my ${text}. Mend March, 1 to 31 March 2027. The Mending Commons.`} />
    </div>
  );
}

/* Mend March — "visible mending": a denim field, one saffron patch, running-stitch rules instead of boxes,
   heavy grotesque display type, plain text for everything people have to read. */
.root {
  --mm-denim: #1e2a4a;
  --mm-thread: #f3efe6;        /* 12.3:1 on denim */
  --mm-thread-muted: #c9cfe0;  /* 9.1:1 on denim */
  --mm-saffron: #f0b44c;       /* fills, and text on denim (7.6:1) */
  --mm-indigo: #34478a;        /* text-safe accent on the page (≥ 6.9:1) */
  --mm-stitch: rgb(52 71 138 / 0.45);
  min-height: 100dvh;
  background: var(--mk-bg);
  color: var(--mk-ink);
  font-family: var(--mk-font-text);
}
:global([data-theme='dark']) .root { --mm-indigo: #a9b8ec; --mm-stitch: rgb(169 184 236 / 0.4); }

/* ── Hero ───────────────────────────────────────────────────────────────── */
.hero { position: relative; overflow: hidden; padding: 36px 16px 44px; background: var(--mm-denim); color: var(--mm-thread); }
.hero :focus-visible { outline-color: var(--mm-saffron); }
.heroInner { display: grid; gap: 8px; max-width: 1120px; margin: 0 auto; }
@container (min-width: 56rem) {
  .hero { padding: 72px 32px 84px; }
  .heroInner { grid-template-columns: minmax(0, 1.3fr) minmax(0, 0.9fr); align-items: center; gap: 40px; }
}
.kicker { margin: 0 0 18px; font-family: var(--mk-font-mono); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mm-saffron); }
.headline { --mk-ink: var(--mm-thread); }
/* Size the composed recipe's heading for a campaign hero (its own clamp tops out at 9cqi). */
.headline h2 { font-size: clamp(2.6rem, 1.4rem + 7cqi, 5.25rem); font-weight: 800; }
.lede { margin: 20px 0 0; max-width: 46ch; font-size: 1.0625rem; line-height: 1.55; color: var(--mm-thread-muted); text-wrap: pretty; }
.when {
  display: flex; flex-wrap: wrap; gap: 12px 36px; margin: 26px 0 0; padding-top: 16px;
  background-image: repeating-linear-gradient(90deg, var(--mm-saffron) 0 12px, transparent 12px 20px); background-size: 100% 2px; background-repeat: no-repeat;
}
.when div { display: grid; gap: 2px; }
.when dt { font-family: var(--mk-font-mono); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mm-thread-muted); }
.when dd { margin: 0; font-family: var(--mk-font-display); font-size: 1.25rem; font-weight: 700; letter-spacing: -0.01em; }
.heroCtas { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 28px; }
.heroArt { display: block; width: 100%; max-width: 460px; height: auto; justify-self: center; }

.primary, .ghostOnDenim, .ghost {
  display: inline-flex; align-items: center; justify-content: center; min-height: 48px; padding: 0 22px; box-sizing: border-box;
  border-radius: var(--mk-radius-s); font: inherit; font-size: 1rem; font-weight: 700; text-decoration: none; cursor: pointer;
}
.primary { border: 0; background: var(--mm-saffron); color: var(--mm-denim); }
.primary:hover { background: #f5c46c; }
.primary[aria-disabled='true'] { background: var(--mk-surface-2); color: var(--mk-ink-muted); cursor: progress; }
.ghostOnDenim { border: 1.5px solid var(--mm-thread); color: var(--mm-thread); font-weight: 600; }
.ghostOnDenim:hover { background: rgb(243 239 230 / 0.1); }
.ghost { min-height: 44px; border: 1px solid var(--mk-line-strong); background: transparent; color: inherit; font-size: 0.9375rem; font-weight: 600; }
.ghost:hover { background: var(--mk-surface-2); }

/* ── Page ───────────────────────────────────────────────────────────────── */
.page { max-width: 1120px; margin: 0 auto; padding: 0 16px 64px; }
.section { padding: 52px 0 8px; scroll-margin-top: 56px; }
.section + .section { border-top: 2px dashed var(--mm-stitch); margin-top: 44px; }
.sectionHead { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 8px 24px; margin-bottom: 22px; }
.sectionHead .small { max-width: 52ch; }
.h2 { margin: 0; font-family: var(--mk-font-display); font-size: clamp(1.875rem, 1.3rem + 2.2cqi, 2.875rem); font-weight: 800; line-height: 1; letter-spacing: -0.035em; }
.h3 { margin: 0 0 4px; font-family: var(--mk-font-display); font-size: 1.25rem; font-weight: 700; letter-spacing: -0.015em; }
.small { margin: 0; font-size: 0.8125rem; line-height: 1.5; color: var(--mk-ink-muted); }

.section > .h2 { margin-bottom: 26px; }
.steps { display: grid; gap: 26px; margin: 0; padding: 0; list-style: none; }
.steps li { position: relative; }
.steps h3 { margin: 0 0 6px; font-family: var(--mk-font-display); font-size: 1.25rem; font-weight: 700; letter-spacing: -0.015em; }
.steps p { margin: 0; max-width: 34ch; line-height: 1.55; color: var(--mk-ink-muted); }
.stepNo { display: grid; place-items: center; width: 44px; height: 44px; margin-bottom: 12px; border-radius: 50%; background: var(--mm-denim); color: var(--mm-saffron); font-family: var(--mk-font-display); font-size: 1.25rem; font-weight: 800; }
@container (min-width: 48rem) {
  .steps { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 32px; }
  .steps li:not(:last-child)::after {
    content: ''; position: absolute; top: 21px; left: 56px; right: -20px; height: 2px;
    background-image: repeating-linear-gradient(90deg, var(--mm-indigo) 0 9px, transparent 9px 16px);
  }
}

/* ── Gallery ────────────────────────────────────────────────────────────── */
.filters { display: flex; flex-wrap: wrap; gap: 8px; }
.chip { min-height: 44px; padding: 0 16px; border: 1px solid var(--mk-line-strong); border-radius: 999px; background: transparent; color: inherit; font: inherit; font-size: 0.875rem; font-weight: 500; }
.chip:hover { background: var(--mk-surface-2); }
.chip[aria-pressed='true'] { border-color: var(--mm-denim); background: var(--mm-denim); color: var(--mm-thread); }
.count { margin: 12px 0 16px; font-size: 0.8125rem; color: var(--mk-ink-muted); }
.grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin: 0; padding: 0; list-style: none; }
@container (min-width: 44rem) { .grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; } }
@container (min-width: 64rem) { .grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.tile { position: relative; display: grid; align-content: start; gap: 3px; padding: 8px 8px 12px; background: var(--mk-surface); border: 1px solid var(--mk-line); }
.tile[hidden] { display: none; }
/* The drawings sit on a linen ground in both themes, like a photo of the mend on a cloth. */
.tileArt { box-sizing: border-box; aspect-ratio: 1; margin-bottom: 8px; padding: 12%; background: #e9e3d6; outline: 2px dashed rgb(52 71 138 / 0.45); outline-offset: -7px; }
:global([data-theme='dark']) .tileArt { background: #d3cbba; }
.tileTitle { margin: 0; padding-inline: 2px; font-size: 0.9375rem; font-weight: 600; line-height: 1.3; }
.tileMeta { margin: 0; padding-inline: 2px; font-size: 0.8125rem; line-height: 1.4; color: var(--mk-ink-muted); }
.tileTag { position: absolute; top: 14px; left: 14px; padding: 2px 7px; border: 1px solid var(--mk-line); background: var(--mk-surface); font-family: var(--mk-font-mono); font-size: 0.625rem; letter-spacing: 0.06em; text-transform: uppercase; }

/* ── Pledge + share card ────────────────────────────────────────────────── */
.pledgeGrid { display: grid; gap: 40px; }
@container (min-width: 60rem) { .pledgeGrid { grid-template-columns: minmax(0, 1fr) minmax(0, 0.92fr); gap: 56px; align-items: start; } }
.form, .done { display: grid; gap: 22px; padding: 20px; background: var(--mk-surface); border: 1px solid var(--mk-line); }
.field { display: grid; gap: 6px; min-width: 0; margin: 0; padding: 0; border: 0; }
.label { padding: 0; font-size: 0.9375rem; font-weight: 600; }
.optional { font-weight: 400; color: var(--mk-ink-muted); }
.input {
  box-sizing: border-box; width: 100%; min-height: 44px; padding: 0 12px;
  border: 1px solid var(--mk-line-strong); border-radius: var(--mk-radius-s); background: var(--mk-bg); color: inherit; font: inherit; font-size: 1rem;
}
.input[aria-invalid='true'] { border-color: var(--mk-danger); box-shadow: inset 4px 0 0 var(--mk-danger); }
.error { margin: 0; font-size: 0.875rem; font-weight: 500; color: var(--mk-danger); }
.choices, .threads, .weeks { display: flex; flex-wrap: wrap; gap: 8px; }
.choice, .thread, .week {
  position: relative; display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 14px; box-sizing: border-box;
  border: 1px solid var(--mk-line-strong); border-radius: 999px; font-size: 0.875rem; cursor: pointer;
}
.choice input, .thread input, .week input { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: pointer; }
.choice:has(input:checked), .week:has(input:checked) { border-color: var(--mm-denim); background: var(--mm-denim); color: var(--mm-thread); }
.choice:has(input[aria-invalid='true']) { border-color: var(--mk-danger); }
.choice:has(input:focus-visible), .thread:has(input:focus-visible), .week:has(input:focus-visible) { outline: 2px solid var(--mk-focus); outline-offset: 2px; }
.check { display: flex; align-items: flex-start; gap: 10px; font-size: 0.9375rem; line-height: 1.45; cursor: pointer; }
.check input { flex: none; width: 22px; height: 22px; margin: 0; accent-color: var(--mm-denim); }
.submitRow { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; }
.done { justify-items: start; gap: 12px; }
.done p { margin: 0; max-width: 48ch; line-height: 1.55; }
.doneMark { width: 56px; height: 56px; }
.donePatch { fill: var(--mm-saffron); }
.doneCheck { fill: none; stroke: var(--mm-denim); stroke-width: 5; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 1; stroke-dashoffset: 0; }
.doneTitle { margin: 0; font-family: var(--mk-font-display); font-size: 1.75rem; font-weight: 800; line-height: 1.05; letter-spacing: -0.03em; }

.card { display: grid; gap: 16px; margin-top: 14px; }
.cardControls { display: grid; gap: 8px; }
.cardInputRow { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; }
.cardInputRow .input { flex: 1 1 200px; width: auto; }
.cardPrefix { font-family: var(--mk-font-serif); font-size: 1.1875rem; font-style: italic; color: var(--mk-ink-muted); }
.threads { margin: 6px 0 0; padding: 0; border: 0; }
.threads legend { margin-bottom: 8px; }
.thread { padding-left: 10px; }
.thread:has(input:checked) { border: 2px solid var(--mm-indigo); font-weight: 700; }
.swatch { width: 18px; height: 18px; border: 1px solid var(--mk-line-strong); border-radius: 50%; }
.cardActions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 6px; }
.canvas { display: block; width: 100%; max-width: 440px; height: auto; aspect-ratio: 1; border: 1px solid var(--mk-line); }

/* ── Leaderboard ────────────────────────────────────────────────────────── */
.board { padding: 18px 16px 20px; background: var(--mk-surface); border: 1px solid var(--mk-line); }
.boardControls { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; margin-bottom: 18px; }
.playBtn { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 16px; border: 0; border-radius: var(--mk-radius-s); background: var(--mm-denim); color: var(--mm-thread); font: inherit; font-size: 0.9375rem; font-weight: 600; }
.playBtn svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; }
.playBtn .solid { fill: currentColor; stroke: none; }
.weeks { margin: 0; padding: 0; border: 0; gap: 6px; }
.week { padding: 0 12px; font-size: 0.8125rem; }
.race { position: relative; }
.raceRow {
  position: absolute; top: 0; left: 0; right: 0; height: 48px; box-sizing: border-box;
  display: grid; grid-template-columns: 24px minmax(0, 1fr) auto; grid-template-areas: 'rank name value' 'rank bar bar'; align-content: center; column-gap: 10px; row-gap: 5px;
  transition: transform var(--mk-duration-slow) var(--mk-ease-emphasized);
}
@container (min-width: 48rem) {
  .raceRow { grid-template-columns: 28px 13rem minmax(0, 1fr) 4ch; grid-template-areas: 'rank name bar value'; }
}
.raceRank { grid-area: rank; font-family: var(--mk-font-mono); font-size: 0.75rem; color: var(--mk-ink-muted); text-align: right; }
.raceName { grid-area: name; overflow: hidden; font-size: 0.875rem; font-weight: 500; white-space: nowrap; text-overflow: ellipsis; }
.raceRow[data-lead] .raceName { font-weight: 700; }
.raceTrack { position: relative; grid-area: bar; height: 12px; overflow: hidden; background: var(--mk-surface-2); }
.raceBar { position: absolute; inset: 0; background: var(--mm-indigo); transform-origin: left center; transition: transform var(--mk-duration-slow) var(--mk-ease-emphasized); }
.raceRow[data-lead] .raceBar { background: var(--mm-saffron); }
.raceValue { grid-area: value; font-family: var(--mk-font-mono); font-size: 0.875rem; font-variant-numeric: tabular-nums; text-align: right; }

.footer { margin-top: 56px; padding-top: 18px; border-top: 2px dashed var(--mm-stitch); font-size: 0.875rem; line-height: 1.55; color: var(--mk-ink-muted); }
.footer p { margin: 0 0 6px; max-width: 70ch; }
